#!/bin/bash
set -e

cd /testbed

# Ensure correct Go version is used
export PATH="/usr/local/go/bin:$PATH"

# The elapsed library uses time.Now() which is affected by the system clock.
# Go uses vDSO for time (bypasses libc), so LD_PRELOAD/faketime won't work.
# Patch the elapsed library in the Go module cache to support FAKE_NOW env var.
ELAPSED_DIR=$(go env GOMODCACHE)/github.com/rvflash/elapsed@v0.2.0
chmod -R u+w "$ELAPSED_DIR" 2>/dev/null || true

cat > "$ELAPSED_DIR/time.go" << 'ELAPSED_EOF'
// Copyright (c) 2017-2018 Hervé Gouchet. All rights reserved.
// Use of this source code is governed by the MIT License
// that can be found in the LICENSE file.

// Package elapsed return the elapsed time since a given time in a human readable format.
package elapsed

import (
	"errors"
	"fmt"
	"math"
	"os"
	"strings"
	"time"
)

type TrID int

const (
	NotYet TrID = iota
	JustNow
	Minute
	Minutes
	Hour
	Hours
	Yesterday
	Days
	Week
	Weeks
	Month
	Months
	Year
	Years
)

type Terms map[TrID]string
type Translation map[string]Terms

var i18n = Translation{
	"en": {
		NotYet:    `not yet`,
		JustNow:   `just now`,
		Minute:    `%d minute ago`,
		Minutes:   `%d minutes ago`,
		Hour:      `%d hour ago`,
		Hours:     `%d hours ago`,
		Yesterday: `yesterday`,
		Days:      `%d days ago`,
		Week:      `%d week ago`,
		Weeks:     `%d weeks ago`,
		Month:     `%d month ago`,
		Months:    `%d months ago`,
		Year:      `%d year ago`,
		Years:     `%d years ago`,
	},
}

var (
	ErrExists     = errors.New("already exists")
	ErrIncomplete = errors.New("missing translation")
	ErrISOCode    = errors.New("invalid language code")
)

func AddTranslation(lang string, tr Terms) error {
	if lang = strings.TrimSpace(lang); lang == "" {
		return ErrISOCode
	}
	if _, ok := i18n[lang]; ok {
		return ErrExists
	}
	for k := range i18n["en"] {
		if _, ok := tr[k]; !ok {
			return ErrIncomplete
		}
	}
	i18n[lang] = tr
	return nil
}

func fakeNow() time.Time {
	if s := os.Getenv("FAKE_NOW"); s != "" {
		if t, err := time.Parse("2006-01-02", s); err == nil {
			return t
		}
	}
	return time.Now()
}

func Time(t time.Time) string {
	return LocalTime(t, "en")
}

func LocalTime(t time.Time, lang string) string {
	if t.IsZero() || fakeNow().Before(t) {
		return tr(NotYet, lang)
	}
	diff := fakeNow().Sub(t)
	s := diff.Seconds()
	d := int(s / 86400)
	switch {
	case s < 60:
		return tr(JustNow, lang)
	case s < 3600:
		min := int(diff.Minutes())
		return fmt.Sprintf(tr(changeIfSing(Minutes, min), lang), min)
	case s < 86400:
		hours := int(diff.Hours())
		return fmt.Sprintf(tr(changeIfSing(Hours, hours), lang), hours)
	case d == 1:
		return tr(Yesterday, lang)
	case d < 7:
		return fmt.Sprintf(tr(changeIfSing(Days, d), lang), d)
	case d < 31:
		nbWeek := int(math.Ceil(float64(d) / 7))
		if nbWeek < 4 {
			return fmt.Sprintf(tr(changeIfSing(Weeks, nbWeek), lang), nbWeek)
		}
		fallthrough
	case d < 365:
		nbMonth := int(math.Ceil(float64(d) / 30))
		if nbMonth < 12 {
			return fmt.Sprintf(tr(changeIfSing(Months, nbMonth), lang), nbMonth)
		}
		fallthrough
	default:
		nbYear := int(math.Ceil(float64(d) / 365))
		return fmt.Sprintf(tr(changeIfSing(Years, nbYear), lang), nbYear)
	}
}

func tr(id TrID, lang string) string {
	ltr, ok := i18n[lang]
	if !ok {
		ltr = i18n["en"]
	}
	return ltr[id]
}

func changeIfSing(id TrID, nb int) TrID {
	if nb != 1 {
		return id
	}
	switch id {
	case Minutes:
		return Minute
	case Hours:
		return Hour
	case Months:
		return Month
	case Weeks:
		return Week
	case Years:
		return Year
	default:
		return id
	}
}
